"""Build self-contained Azerbaijani and Russian language-switch audit reports."""
import json
from pathlib import Path
from collections import Counter
p=Path('docs/reviews/language-switch-20261102')
load=lambda name:json.loads((p/name).read_text('utf-8'))
before,after,bs,ats=map(load,['before.json','after.json','before-scroll.json','after-scroll.json'])
key=lambda r:(r['from'],r['to'],r['id'])
assert all(len(x)==5120 and len({key(r) for r in x})==5120 for x in [before,after,bs,ats])
records=[]
for scenario,left,right in [('navigation',before,after),('scroll',bs,ats)]:
 old={key(r):r for r in left}
 for r in sorted(right,key=key):
  a=old[key(r)];records.append({'scenario':scenario,'story':r['id'],'from':r['from'],'to':r['to'],'before':a['pass'],'after':r['pass'],'previous':a['outcome'],'previousTarget':a.get('url',a.get('href','')),'current':r['outcome'],'source':r.get('source',a.get('source','')),'target':r.get('url',r.get('href','')),'error':r.get('error','')})
for name in ['edge-cases.json','poem-cases.json','expanded-poem-check.json']:
 for r in load(name):records.append({'scenario':r['scenario'],'story':r.get('id','friend-of-allah'),'from':r['from'],'to':r['to'],'before':None,'after':r['pass'],'previous':'','current':'pass' if r['pass'] else 'fail','source':'','target':r.get('url',''),'error':r.get('error',''),'message':r.get('message',''),'width':r.get('width','')})
for r in load('poem-menu-check.json'):
 records.append({'scenario':'poem-menu','story':'flowers','from':'az','to':r['to'],'before':None,'after':r['pass'],'previous':'','current':'pass','source':'','target':'','error':'','width':r['width']})
titles={}
for lang in ['az','en','de','ru','ky']:
 raw=Path(lang,'assets/stories-data.js').read_text('utf-8');catalog=json.loads(raw.split('=',1)[1].strip().rstrip(';'))
 for c in catalog['categories']:
  for story in c['stories']:titles[(lang,story['stem'])]=story['title']
for i,r in enumerate(records,1):r['id']=f'LS-{i:05d}';r['title']=titles.get((r['from'],r['story']),r['story'])
summary={'navigation':{'tested':len(after),'passed':sum(r['pass'] for r in after),'failed':sum(not r['pass'] for r in after)},'scroll':{'tested':len(ats),'passed':sum(r['pass'] for r in ats),'failed':sum(not r['pass'] for r in ats)},'poems':dict(Counter('passed' if r['pass'] else 'failed' for r in load('poem-cases.json'))),'edges':dict(Counter('passed' if r['pass'] else 'failed' for r in load('edge-cases.json')))}
for name,file in [('poems','poem-cases.json'),('edges','edge-cases.json'),('menu','poem-menu-check.json'),('expanded_poems','expanded-poem-check.json')]:
 a=load(file);summary[name]={'tested':len(a),'passed':sum(r['pass'] for r in a),'failed':sum(not r['pass'] for r in a)}
(p/'summary.json').write_text(json.dumps(summary,indent=2),'utf-8')
ui={
'az':{'title':'Dil dəyişdirilərkən hekayənin qorunması — yoxlama hesabatı','intro':'Yerli versiya yoxlanılıb. Mətnlər və illüstrasiyalar dəyişdirilməyib; dəyişikliklər istehsal serverinə yerləşdirilməyib.','cause':'Səbəb və düzəliş','details':['Əvvəlki məntiq URL-də qalan köhnə hekayə identifikatorunu hazırda oxunan hekayədən üstün tuturdu. Yeni məntiq görünən hekayəni və ya genişləndirilmiş oxu görünüşündəki hekayəni müəyyənləşdirir.','Vahid marşrut xəritəsi tools/story-build-manifest.json faylından yaradılır. Hər dilin mövcud hekayə ünvanı ayrıca saxlanılır; olmayan tərcümə üçün uydurma ünvan yaradılmır.','Hekayə üzrə dil seçimi düzgün ünvana keçir. Axtarış sorğusu saxlanılır və oxunan hekayə tərcümədə həmin sorğuya uyğun gəlməsə də görünür. Genişləndirilmiş oxu görünüşü bərpa edilir.','Şeirlərin mövcud tərcümələri tools/poem-translations.json faylında açıq şəkildə göstərilir. Tərcüməsi olmayan dil seçildikdə səhifə, şeir, cari dil və oxu mövqeyi dəyişmir; seçilmiş dildə qısa bildiriş göstərilir. Tərcüməsi mövcud olan şeirlər üçün normal keçid saxlanılır.'],'limits':'Əhatə və məhdudiyyətlər','limit':'1 280 dil versiyası × 4 digər dil = 5 120 istiqamətli keçid. Bundan əlavə, sürüşdürmədən sonrakı 5 120 keçidin ünvanı yoxlanılıb. Tam keçid matrisi Chromium-da faktiki kliklərlə sınaqdan keçirilib. Matrisdə böyük şəkillər və şrift yükləmələri söndürülüb; mobil və şeir sınaqlarında normal yükləmə istifadə olunub. Vaxt həddini aşan hallar ayrıca yenidən yoxlanılıb. Əvvəlki sürüşdürmə davranışı saxlanmış ilkin skript və üslublarla təkrar yoxlanılıb. İstehsal serveri və ayrıca iPad/Safari brauzeri bu mərhələdə yoxlanılmayıb. Hazırda beş şeirin hamısı yalnız azərbaycancadır; tərcüməli şeir üçün yoxlama yaddaşda yaradılmış sınaq təsnifatı ilə aparılıb, məzmun dəyişdirilməyib.','exceptions':'Yalnız azərbaycanca olan şeirlər','search':'Bütün sahələrdə axtarış','all':'Hamısı','scenario':'Sınaq','from':'İlkin dil','to':'Seçilmiş dil','status':'Son nəticə','pass':'Uğurlu','fail':'Uğursuz','before':'Əvvəl','after':'Sonra','story':'Hekayə / şeir','previous':'Əvvəlki nəticə','current':'Son nəticə','source':'İlkin ünvan','target':'Nəticə ünvanı','error':'Təfərrüat','show':'Göstərilir','of':'cəmi','prev':'Əvvəlki','next':'Növbəti','theme':'Görünüş','print':'Çap','navigation':'Faktiki dil keçidi','scroll':'Sürüşdürmədən sonra keçid ünvanı','filtered-list':'Mobil axtarış konteksti','expanded-reading':'Genişləndirilmiş oxu','unavailable-poem':'Tərcüməsi olmayan şeir','translated-poem-fixture':'Tərcüməli şeir üçün sınaq nümunəsi','same-story':'Eyni hekayə açılıb','wrong-story-context':'Başqa hekayənin ünvanı','correct-context':'Düzgün hekayə konteksti','poem-unavailable-stayed':'Şeir və cari dil dəyişməyib; bildiriş göstərilib','missing-translation-without-notice':'Tərcümə yoxdur, bildiriş göstərilməyib','navigation-error':'Keçid / yükləmə vaxtı xətası','list-or-wrong-scroll':'Oxu mövqeyi bərpa olunmayıb'},
'ru':{'title':'Сохранение рассказа при смене языка — отчёт о проверке','intro':'Проверена локальная версия. Тексты и иллюстрации не изменены; обновления на рабочий сервер не опубликованы.','cause':'Причина и исправление','details':['Прежняя логика отдавала приоритет старому идентификатору в адресной строке, а не рассказу, к которому читатель прокрутил страницу. Новая логика определяет видимый рассказ или рассказ в развёрнутом режиме чтения.','Единая карта маршрутов создаётся из tools/story-build-manifest.json. В ней хранится фактический адрес каждого перевода; для отсутствующих переводов адрес не выдумывается.','Переключение ведёт на правильный рассказ. Поисковый запрос сохраняется, а читаемый рассказ остаётся видимым, даже если перевод не соответствует запросу. Развёрнутый режим чтения восстанавливается.','Доступные переводы каждого стихотворения явно перечислены в tools/poem-translations.json. При выборе отсутствующего перевода страница, стихотворение, текущий язык и позиция чтения остаются прежними; короткое сообщение показывается на выбранном языке. Для имеющихся переводов сохраняется обычный переход.'],'limits':'Объём и ограничения','limit':'1 280 языковых версий × 4 других языка = 5 120 направленных переходов. Дополнительно проверены 5 120 адресов переключения после прокрутки. Полная матрица переходов выполнена фактическими кликами в Chromium. В матрице отключалась загрузка больших изображений и шрифтов; мобильные проверки и проверки стихотворений выполнялись с обычной загрузкой. Случаи превышения времени ожидания проверены повторно отдельно. Прежнее поведение после прокрутки воспроизведено с сохранёнными исходными скриптами и стилями. Рабочий сервер и отдельное устройство iPad/Safari на этом этапе не проверялись. Все пять стихотворений сейчас доступны только на азербайджанском; поведение переведённого стихотворения проверено с тестовой классификацией в памяти, без изменения содержимого сайта.','exceptions':'Стихотворения только на азербайджанском','search':'Поиск по всем полям','all':'Все','scenario':'Проверка','from':'Исходный язык','to':'Выбранный язык','status':'Итог','pass':'Пройдено','fail':'Не пройдено','before':'До','after':'После','story':'Рассказ / стихотворение','previous':'Прежний результат','current':'Итоговый результат','source':'Исходный адрес','target':'Полученный адрес','error':'Подробности','show':'Показано','of':'из','prev':'Назад','next':'Далее','theme':'Тема','print':'Печать','navigation':'Фактическое переключение','scroll':'Адрес после прокрутки','filtered-list':'Мобильный поиск','expanded-reading':'Развёрнутое чтение','unavailable-poem':'Отсутствующий перевод стихотворения','translated-poem-fixture':'Тестовый пример переведённого стихотворения','same-story':'Открыт тот же рассказ','wrong-story-context':'Адрес другого рассказа','correct-context':'Правильный рассказ','poem-unavailable-stayed':'Стихотворение и язык сохранены; сообщение показано','missing-translation-without-notice':'Перевода нет, сообщение отсутствует','navigation-error':'Ошибка перехода / ожидания загрузки','list-or-wrong-scroll':'Позиция чтения не восстановлена'}}
