css='''*{box-sizing:border-box}html{color-scheme:light dark}body{margin:0;background:#f4f7fa;color:#132c43;font:16px/1.5 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:2rem}p,li{max-width:100ch}.cards,.filters{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.card{padding:14px;border:1px solid #b9cad8;border-radius:8px;background:#fff}.filters{position:sticky;top:0;background:inherit;padding:10px 0;z-index:2}label{display:flex;flex-direction:column;gap:4px;min-width:0;max-width:100%}select{max-width:min(85vw,330px)}input,select,button{font:inherit;padding:9px;border:1px solid #8ca7bd;border-radius:5px;background:#fff;color:inherit}input{width:min(85vw,360px)}button{cursor:pointer}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:10px;border-bottom:1px solid #bccddb;vertical-align:top}th button{font-weight:bold}summary{cursor:pointer}code,.detail{overflow-wrap:anywhere}.table{overflow:auto}.detail{max-width:65ch;padding:12px}.bad{font-weight:bold;color:#b32731}.good{color:#176243}.dark{background:#101c28;color:#e6eef5}.dark .card,.dark input,.dark select,.dark button{background:#203244}.dark .good{color:#96e4b7}.dark .bad{color:#ffadb4}@media(prefers-color-scheme:dark){body:not(.light){background:#101c28;color:#e6eef5}body:not(.light) .card,body:not(.light) input,body:not(.light) select,body:not(.light) button{background:#203244}body:not(.light) .good{color:#96e4b7}body:not(.light) .bad{color:#ffadb4}}@media print{body,.card,button,.good,.bad{background:white!important;color:black!important}.filters,.pager{display:none}.table{overflow:visible}td{font-size:9pt}.detail{max-width:none}details::details-content{display:block!important}}'''
js=r'''
const {rows:R,u:U}=JSON.parse(document.querySelector('#data').textContent),$=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0,sort='id',direction=1,printing=false;
for(const k of ['scenario','from','to'])for(const v of [...new Set(R.map(r=>r[k]))].sort())$('#'+k).add(new Option(U[v]||v.toUpperCase(),v));
function render(){let q=$('#q').value.toLocaleLowerCase(document.documentElement.lang);let a=R.filter(r=>(!q||(JSON.stringify(r)+' '+(U[r.scenario]||'')+' '+(U[r.current]||'')+' '+(U[r.previous]||'')).toLocaleLowerCase(document.documentElement.lang).includes(q))&&['scenario','from','to'].every(k=>!$('#'+k).value||r[k]===$('#'+k).value)&&(!$('#status').value||($('#status').value==='before-fail'?r.before===false:String(r.after)===$('#status').value))).sort((a,b)=>direction*String(a[sort]).localeCompare(String(b[sort])));page=Math.min(page,Math.max(0,Math.ceil(a.length/100)-1));let shown=printing?a:a.slice(page*100,page*100+100);$('#counter').textContent=`${U.show} ${shown.length} ${U.of} ${a.length} / ${R.length}`;$('#rows').innerHTML=shown.map(r=>`<tr><td>${r.id}</td><td>${U[r.scenario]||e(r.scenario)}</td><td>${r.from.toUpperCase()} → ${r.to.toUpperCase()}</td><td><details><summary>${e(r.title)} <small>(${e(r.story)})</small></summary><div class="detail"><b>${U.previous}:</b> ${U[r.previous]||e(r.previous)}${r.previousTarget?`<p>${U.previous_target}: <code>${e(r.previousTarget)}</code></p>`:''}<br><b>${U.current}:</b> ${U[r.current]||e(r.current)}<p>${U.source}: <code>${e(r.source)}</code></p><p>${U.target}: <code>${e(r.target)}</code></p><p>${e(r.message||'')} ${e(r.error||'')}</p>${r.width?e(r.width)+' px':''}</div></details></td><td class="${r.before===false?'bad':'good'}">${r.before===null?'—':r.before?U.pass:U.fail}</td><td class="${r.after?'good':'bad'}">${r.after?U.pass:U.fail}</td></tr>`).join('');$('#prev').disabled=page===0;$('#next').disabled=(page+1)*100>=a.length}
for(const k of ['q','scenario','from','to','status'])$('#'+k).oninput=()=>{page=0;render()};$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{direction=sort===b.dataset.sort?-direction:1;sort=b.dataset.sort;render()});$('#theme').onclick=()=>{let dark=document.body.classList.contains('dark')||(!document.body.classList.contains('light')&&matchMedia('(prefers-color-scheme:dark)').matches);document.body.classList.toggle('dark',!dark);document.body.classList.toggle('light',dark)};$('#print').onclick=()=>print();addEventListener('beforeprint',()=>{printing=true;render();document.querySelectorAll('details').forEach(d=>d.open=true)});addEventListener('afterprint',()=>{printing=false;render()});render();
'''
