 for name,file in [('unavailable-poem','poem-cases.json'),('filtered-list','edge-cases.json')]:
  a=load(file);h+=f'<div class="card"><b>{u[name]}: {len(a)}</b><br>{sum(r["pass"] for r in a)} ✓ / {sum(not r["pass"] for r in a)} ✗</div>'
 h+='</div>'
